sys_ui_action.client_script_v2:
if (g_form.modified) {
    alert(getMessage("x_hccc_vc.alert.save.record"));

	//return;
}

function onClick(g_form) {
    var fields = [{
        type: 'textarea',
        name: 'work_notes',
        label: 'Work notes'
    }];

    var sysId = g_form.getUniqueValue();
    var tblName = g_form.getTableName();

    g_modal.showFields({
        title: getMessage('Escalate Dialog'),
        fields: fields,
        instruction: getMessage('Please enter work notes for escalation'),
        size: 'md'
    }).then(function(fieldValues) {
        //get the work note entered
        var newWorkNote = fieldValues.updatedFields[0].value;
        //Call the Ajax function that handles adding worknotes and state
        var ga = new GlideAjax("sn_hr_core.hr_CaseAjax");
        s.addParam("sysparm_name", "escalateAction");
        ga.addParam("sysparm_obj_id", sysId);
        ga.addParam("sysparm_table_name", tblName);
        ga.addParam("sysparm_work_note", newWorkNote);
        ga.getXML(addWorkNotes);

        function addWorkNotes(response) {
            g_form.save();
        }
    });
}
